//refAssemblies: System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');

// srcds writes steam_appid.txt next to itself only during its first run, which therefore starts without Steam.
// Writing it before every start makes the first start work too.
var appIdFile = Path.Combine(root, "steam_appid.txt");
NoLink(root, appIdFile);
if (!File.Exists(appIdFile) || File.ReadAllText(appIdFile).Trim('\0', '\r', '\n', ' ') != "362890")
{
    File.WriteAllText(appIdFile, "362890\n");
    // Scripts run as root on Linux: give the file to the service user (owner of the service root).
    if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetFileOwnerAutoDetect(appIdFile);
    ScriptConsole.WriteLine((object)"Wrote steam_appid.txt (362890).");
}

// -condebug appends to console.log forever; keep only the previous run next to the new one.
var log = Path.Combine(root, "bms", "console.log");
var previousLog = Path.Combine(root, "bms", "console.previous.log");
NoLink(root, log);
NoLink(root, previousLog);
if (File.Exists(log)) File.Move(log, previousLog, true);

if (System.OperatingSystem.IsLinux())
{
    // The Steam download does not keep the exec bit.
    foreach (var name in new[] { "srcds_run", "srcds_linux" })
    {
        var path = Path.Combine(root, name);
        NoLink(root, path);
        if (!File.Exists(path)) continue;
        var mode = File.GetUnixFileMode(path);
        var wanted = mode | UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute;
        if (mode != wanted) { File.SetUnixFileMode(path, wanted); ScriptConsole.WriteLine((object)("Made " + name + " executable.")); }
    }

    // srcds_linux and the engine are 32-bit programs: install the 32-bit system libraries they need when the host
    // lacks them (Debian/Ubuntu: apt-get, Red Hat: dnf or yum). The check reads the system library cache only; it
    // never runs the server's own files as root.
    var packages = new Dictionary<string, (string[] Apt, string[] Rpm)>
    {
        ["libc.so.6"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libm.so.6"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libdl.so.2"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libpthread.so.0"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["librt.so.1"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libgcc_s.so.1"] = (new[] { "lib32gcc-s1", "lib32gcc1" }, new[] { "libgcc.i686" }),
        ["libstdc++.so.6"] = (new[] { "lib32stdc++6" }, new[] { "libstdc++.i686" }),
    };
    var missing = new List<string>();
    if (!File.Exists("/lib/ld-linux.so.2")) missing.Add("libc.so.6");
    var present32 = new HashSet<string>();
    Run("/sbin/ldconfig", new[] { "-p" }, out var cache);
    if (string.IsNullOrEmpty(cache)) Run("ldconfig", new[] { "-p" }, out cache);
    foreach (var line in cache.Split('\n'))
    {
        var m = System.Text.RegularExpressions.Regex.Match(line, @"^\s*(\S+)\s+\(([^)]*)\)");
        if (m.Success && m.Groups[2].Value.StartsWith("libc6") && !m.Groups[2].Value.Contains("x86-64")) present32.Add(m.Groups[1].Value);
    }
    missing.AddRange(packages.Keys.Where(k => !present32.Contains(k)));
    foreach (var group in missing.Distinct().GroupBy(s => string.Join(",", packages[s].Apt)))
    {
        var soname = group.First();
        var candidates = packages[soname];
        ScriptConsole.WriteLine((object)("32-bit " + string.Join(", ", group) + " missing on this host; installing it."));
        var apt = Shell("command -v apt-get");
        string tool;
        if (apt)
        {
            Shell("dpkg --print-foreign-architectures | grep -q i386 || dpkg --add-architecture i386");
            tool = "DEBIAN_FRONTEND=noninteractive apt-get install -y ";
        }
        else tool = Shell("command -v dnf") ? "dnf install -y " : "yum install -y ";
        var names = apt ? candidates.Apt : candidates.Rpm;
        var installed = names.Any(p => Shell(tool + p));
        if (!installed && apt && Shell("apt-get update")) installed = names.Any(p => Shell(tool + p));
        if (!installed) throw new Exception("32-bit " + soname + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
        ScriptConsole.WriteLine((object)("Installed " + string.Join(", ", names) + "."));
    }
}

// Fixed commands only (no service or customer values reach the shell).
bool Shell(string command) => Run("/bin/sh", new[] { "-c", command }, out _);

bool Run(string file, string[] arguments, out string output)
{
    output = "";
    try
    {
        var startInfo = new ProcessStartInfo(file) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };
        foreach (var argument in arguments) startInfo.ArgumentList.Add(argument);
        using (var process = Process.Start(startInfo))
        {
            var stdout = process.StandardOutput.ReadToEndAsync();
            var stderr = process.StandardError.ReadToEndAsync();
            process.WaitForExit();
            output = stdout.Result + stderr.Result;
            return process.ExitCode == 0;
        }
    }
    catch (System.ComponentModel.Win32Exception)
    {
        return false;
    }
}

// Linux: this script runs as root in a folder the service account can write to. A symbolic link anywhere between
// top and path could point it at any file on the host, so the script stops instead of following one.
void NoLink(string top, string path)
{
    if (!System.OperatingSystem.IsLinux()) return;
    top = Path.GetFullPath(top).TrimEnd('/');
    var full = Path.GetFullPath(path);
    if (full != top && !full.StartsWith(top + "/", StringComparison.Ordinal)) throw new Exception(path + " is outside " + top + ".");
    var current = top;
    foreach (var part in full.Substring(top.Length).Split('/', StringSplitOptions.RemoveEmptyEntries))
    {
        current = current + "/" + part;
        var info = new FileInfo(current);
        if (info.LinkTarget != null) throw new Exception(current.Substring(top.Length + 1) + " is a symbolic link; remove it and try again.");
        if (!info.Exists && !Directory.Exists(current)) break;
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Black Mesa servers download and mount Workshop items themselves: the ids listed in bms/subscribed_file_ids.txt
// are downloaded (and kept up to date) by the server's Steam client when it starts, into
// addons/workshop/content/362890/<id>, and players get them from the Workshop. The panel downloaded this item to
// learn its map names; hand that copy to the server, add the id to the list and its maps to the map cycle.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]{1,20}$")) throw new Exception("Unexpected Workshop id: " + fileId);
string downloaded = Convert.ToString(Dynamic.InstallPath);

var target = ServerItemDir(fileId);
var maps = new List<string>();
if (!string.IsNullOrEmpty(downloaded) && Directory.Exists(downloaded))
{
    NoLinkInside(downloaded);
    maps = FindMaps(downloaded);
    if (!string.Equals(Path.GetFullPath(downloaded).TrimEnd('/', '\\'), target, StringComparison.Ordinal))
    {
        NoLinkInside(target);
        NoLink(Path.GetDirectoryName(target));
        if (Directory.Exists(target)) Directory.Delete(target, true);
        Directory.CreateDirectory(Path.GetDirectoryName(target));
        Directory.Move(downloaded, target);
        // The server's Steam client checks the copy and replaces it when it is outdated.
        foreach (var staging in Directory.GetDirectories(target, ".DepotDownloader", SearchOption.TopDirectoryOnly)) Directory.Delete(staging, true);
        GiveToServiceUser(Path.Combine(Root(), "addons"), true);
    }
}
if (maps.Count == 0) maps = FindMaps(target);

// The server mounts the folder, not the packages in it: unpack them so it finds the maps.
UnpackItem(target);

var list = ReadList();
if (!list.Contains(fileId)) list.Add(fileId);
WriteList(list);
ScriptConsole.WriteLine((object)("Added Workshop item " + fileId + " to bms/subscribed_file_ids.txt."));

if (maps.Count > 0)
{
    var cycle = ReadCycle();
    foreach (var map in maps.Where(m => !cycle.Contains(m, StringComparer.OrdinalIgnoreCase))) cycle.Add(map);
    WriteCycle(cycle);
    ScriptConsole.WriteLine((object)("Added " + string.Join(", ", maps) + " to the map cycle. Change to it with: changelevel " + maps[0]));
}
else
{
    ScriptConsole.WriteLine((object)"The item contains no map; the server loads it as an add-on.");
}
ScriptConsole.WriteLine((object)"Restart the server to load it. Some old Workshop items use Steam's legacy file format, which a dedicated server cannot download: the console then shows \"failed to download\" for the item.");

// --- Shared helpers: the server's own Workshop list (bms/subscribed_file_ids.txt) and the map cycle. ---
string Root() => Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
string ListFile() => Path.Combine(Root(), "bms", "subscribed_file_ids.txt");
string CycleFile() => Path.Combine(Root(), "bms", "cfg", "mapcycle.txt");
// Where the server's own Steam client keeps and mounts its Workshop items.
string ServerItemDir(string id) => Path.Combine(Root(), "addons", "workshop", "content", "362890", id);

List<string> ReadList()
{
    NoLink(ListFile());
    if (!File.Exists(ListFile())) return new List<string>();
    return File.ReadAllLines(ListFile()).Select(l => l.Trim()).Where(l => Regex.IsMatch(l, "^[0-9]+$")).Distinct().ToList();
}

void WriteList(List<string> ids)
{
    NoLink(ListFile());
    File.WriteAllText(ListFile(), string.Join("\n", ids) + (ids.Count > 0 ? "\n" : ""));
    GiveToServiceUser(ListFile(), false);
}

List<string> ReadCycle()
{
    NoLink(CycleFile());
    return File.Exists(CycleFile()) ? File.ReadAllLines(CycleFile()).Select(l => l.Trim()).Where(l => l != "").ToList() : new List<string>();
}

void WriteCycle(List<string> maps)
{
    NoLink(CycleFile());
    File.WriteAllText(CycleFile(), string.Join("\n", maps) + "\n");
    GiveToServiceUser(CycleFile(), false);
}

// Scripts run as root on Linux: files they create must belong to the service user (the owner of the service root).
void GiveToServiceUser(string path, bool directory)
{
    if (!System.OperatingSystem.IsLinux()) return;
    if (directory) Globals.OperatingSystem.SetDirectoryOwnerAutoDetect(path, true);
    else Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

// Linux: this script runs as root in a folder the service account can write to. A symbolic link anywhere between
// the service root and path could point it at any file on the host, so the script stops instead of following one.
void NoLink(string path)
{
    var top = Root();
    var full = Path.GetFullPath(path);
    var sep = System.OperatingSystem.IsWindows() ? "\\" : "/";
    if (!full.StartsWith(top + sep, System.OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal))
        throw new Exception(path + " is outside the service folder.");
    if (!System.OperatingSystem.IsLinux()) return;
    var current = top;
    foreach (var part in full.Substring(top.Length).Split('/', StringSplitOptions.RemoveEmptyEntries))
    {
        current = current + "/" + part;
        var info = new FileInfo(current);
        if (info.LinkTarget != null) throw new Exception(current.Substring(top.Length + 1) + " is a symbolic link; remove it and try again.");
        if (!info.Exists && !Directory.Exists(current)) break;
    }
}

// No symbolic link anywhere inside a folder the script is about to move or delete.
void NoLinkInside(string dir)
{
    NoLink(dir);
    if (!System.OperatingSystem.IsLinux() || !Directory.Exists(dir)) return;
    foreach (var entry in new DirectoryInfo(dir).EnumerateFileSystemInfos("*", new EnumerationOptions { RecurseSubdirectories = true, AttributesToSkip = 0 }))
        if (entry.LinkTarget != null) throw new Exception(entry.FullName.Substring(Root().Length + 1) + " is a symbolic link; remove it and try again.");
}

// Map names (maps/<name>.bsp) of a Workshop item: loose .bsp files or .bsp entries inside a .vpk.
List<string> FindMaps(string dir)
{
    var names = new List<string>();
    if (!Directory.Exists(dir)) return names;
    foreach (var f in Directory.GetFiles(dir, "*.bsp", SearchOption.AllDirectories))
        names.Add(Path.GetFileNameWithoutExtension(f));
    foreach (var f in Directory.GetFiles(dir, "*.vpk", SearchOption.AllDirectories))
    {
        if (Regex.IsMatch(Path.GetFileName(f), "_[0-9]{3}\\.vpk$")) continue; // data chunks of a multi-file vpk
        try { names.AddRange(VpkMaps(f)); } catch { }
    }
    // Map names go into mapcycle.txt and console commands: keep plain names only.
    return names.Where(n => Regex.IsMatch(n, "^[A-Za-z0-9_.-]{1,64}$")).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
}

List<string> VpkMaps(string file)
{
    var maps = new List<string>();
    using (var r = new BinaryReader(File.OpenRead(file)))
    {
        if (r.ReadUInt32() != 0x55aa1234) return maps;
        var version = r.ReadUInt32();
        r.ReadUInt32(); // tree size
        if (version == 2) { r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt32(); }
        string Str() { var b = new List<byte>(); byte c; while ((c = r.ReadByte()) != 0) b.Add(c); return Encoding.UTF8.GetString(b.ToArray()); }
        while (true)
        {
            var ext = Str(); if (ext == "") break;
            while (true)
            {
                var path = Str(); if (path == "") break;
                while (true)
                {
                    var name = Str(); if (name == "") break;
                    r.ReadUInt32(); var preload = r.ReadUInt16(); r.ReadUInt16(); r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt16();
                    if (preload > 0) r.ReadBytes(preload);
                    if (ext.Equals("bsp", StringComparison.OrdinalIgnoreCase) && path.Trim('/').Equals("maps", StringComparison.OrdinalIgnoreCase)) maps.Add(name);
                }
            }
        }
    }
    return maps;
}
// The server mounts a Workshop item's folder as a loose game folder, not the .vpk packages inside it, so a map packed
// in a .vpk is "not found". Unpack the packages next to them (maps/, materials/, models/, sound/ ...). A marker file
// remembers which package versions were unpacked; the server's Steam client replaces the packages on an update and
// the next unpack (before every start) refreshes the loose files.
void UnpackItem(string dir)
{
    NoLinkInside(dir);
    if (!Directory.Exists(dir)) return;
    var marker = Path.Combine(dir, ".tca_unpacked");
    var packages = Directory.GetFiles(dir, "*.vpk", SearchOption.TopDirectoryOnly)
        .Where(f => !Regex.IsMatch(Path.GetFileName(f), "_[0-9]{3}\\.vpk$")).OrderBy(f => f, StringComparer.Ordinal).ToList();
    var state = string.Join("\n", packages.Select(f => Path.GetFileName(f) + " " + new FileInfo(f).Length + " " + File.GetLastWriteTimeUtc(f).Ticks));
    if (packages.Count == 0 || (File.Exists(marker) && File.ReadAllText(marker) == state)) return;
    var count = 0;
    foreach (var package in packages) count += UnpackVpk(dir, package);
    File.WriteAllText(marker, state);
    GiveToServiceUser(dir, true);
    ScriptConsole.WriteLine((object)("Unpacked " + count + " files of Workshop item " + Path.GetFileName(dir) + " for the server."));
}

int UnpackVpk(string dir, string package)
{
    var count = 0;
    var dirFile = Path.GetFileName(package);
    var chunkBase = dirFile.EndsWith("_dir.vpk", StringComparison.OrdinalIgnoreCase) ? dirFile.Substring(0, dirFile.Length - 8) : null;
    var entries = new List<(string Path, ushort Archive, uint Offset, uint Length, byte[] Preload)>();
    long dataStart;
    using (var r = new BinaryReader(File.OpenRead(package)))
    {
        if (r.ReadUInt32() != 0x55aa1234) return 0;
        var version = r.ReadUInt32();
        var treeSize = r.ReadUInt32();
        if (version == 2) { r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt32(); }
        var headerSize = version == 2 ? 28 : 12;
        dataStart = headerSize + treeSize;
        string Str() { var b = new List<byte>(); byte c; while ((c = r.ReadByte()) != 0) { b.Add(c); if (b.Count > 512) throw new Exception("Bad package " + dirFile); } return Encoding.UTF8.GetString(b.ToArray()); }
        while (true)
        {
            var ext = Str(); if (ext == "") break;
            while (true)
            {
                var folder = Str(); if (folder == "") break;
                while (true)
                {
                    var name = Str(); if (name == "") break;
                    r.ReadUInt32(); // crc
                    var preloadLength = r.ReadUInt16();
                    var archive = r.ReadUInt16();
                    var offset = r.ReadUInt32();
                    var length = r.ReadUInt32();
                    r.ReadUInt16(); // terminator
                    var preload = preloadLength > 0 ? r.ReadBytes(preloadLength) : new byte[0];
                    var relative = (folder.Trim() == "" ? "" : folder.Trim('/') + "/") + name + "." + ext;
                    entries.Add((relative, archive, offset, length, preload));
                }
            }
        }
    }
    foreach (var e in entries)
    {
        // Package paths are data from the Workshop: plain relative names only, inside the item folder.
        if (!Regex.IsMatch(e.Path, "^[A-Za-z0-9 _.()+,'&!#@~=\\[\\]{}$%-]+(/[A-Za-z0-9 _.()+,'&!#@~=\\[\\]{}$%-]+)*$") || e.Path.Split('/').Any(p => p == "." || p == ".."))
        {
            ScriptConsole.WriteLine((object)("Skipped a file with an unusual name in " + dirFile + "."));
            continue;
        }
        var target = Path.GetFullPath(Path.Combine(dir, e.Path));
        if (!target.StartsWith(Path.GetFullPath(dir).TrimEnd('/', '\\') + Path.DirectorySeparatorChar, StringComparison.Ordinal)) continue;
        string source;
        long position;
        if (e.Archive == 0x7fff) { source = package; position = dataStart + e.Offset; }
        else if (chunkBase != null) { source = Path.Combine(dir, chunkBase + "_" + e.Archive.ToString("000") + ".vpk"); position = e.Offset; }
        else continue;
        NoLink(source);
        NoLink(target);
        Directory.CreateDirectory(Path.GetDirectoryName(target));
        NoLink(target);
        using (var output = new FileStream(target, FileMode.Create, FileAccess.Write))
        {
            output.Write(e.Preload, 0, e.Preload.Length);
            if (e.Length > 0)
            {
                using (var input = File.OpenRead(source))
                {
                    if (position + e.Length > input.Length) throw new Exception("Bad package " + dirFile + ": " + e.Path + " is outside the file.");
                    input.Position = position;
                    var buffer = new byte[81920];
                    long left = e.Length;
                    while (left > 0)
                    {
                        var read = input.Read(buffer, 0, (int)Math.Min(buffer.Length, left));
                        if (read <= 0) throw new Exception("Bad package " + dirFile + ".");
                        output.Write(buffer, 0, read);
                        left -= read;
                    }
                }
            }
        }
        count++;
    }
    return count;
}
// --- end of shared helpers ---

