// Scripts run as root on Linux: files they create must belong to the service user (the owner of the service root).
void GiveToServiceUser(string path, bool directory)
{
    if (!System.OperatingSystem.IsLinux()) return;
    if (directory) Globals.OperatingSystem.SetDirectoryOwnerAutoDetect(path, true);
    else Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

// Linux: this script runs as root in a folder the service account can write to. A symbolic link anywhere between
// the service root and path could point it at any file on the host, so the script stops instead of following one.
void NoLink(string path)
{
    var top = Root();
    var full = Path.GetFullPath(path);
    var sep = System.OperatingSystem.IsWindows() ? "\\" : "/";
    if (!full.StartsWith(top + sep, System.OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal))
        throw new Exception(path + " is outside the service folder.");
    if (!System.OperatingSystem.IsLinux()) return;
    var current = top;
    foreach (var part in full.Substring(top.Length).Split('/', StringSplitOptions.RemoveEmptyEntries))
    {
        current = current + "/" + part;
        var info = new FileInfo(current);
        if (info.LinkTarget != null) throw new Exception(current.Substring(top.Length + 1) + " is a symbolic link; remove it and try again.");
        if (!info.Exists && !Directory.Exists(current)) break;
    }
}

// No symbolic link anywhere inside a folder the script is about to move or delete.
void NoLinkInside(string dir)
{
    NoLink(dir);
    if (!System.OperatingSystem.IsLinux() || !Directory.Exists(dir)) return;
    foreach (var entry in new DirectoryInfo(dir).EnumerateFileSystemInfos("*", new EnumerationOptions { RecurseSubdirectories = true, AttributesToSkip = 0 }))
        if (entry.LinkTarget != null) throw new Exception(entry.FullName.Substring(Root().Length + 1) + " is a symbolic link; remove it and try again.");
}

